define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_61.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e215315","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_63.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e215419","topics":[]},{"title":"Applying LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Apply LOTO before servicing the GOC or items in the operator workspace. Applying LOTO makes sure the environment is safe when working on these items.<\/p>","href":"t_Applying-LOTO-GOCandOWLOTO-Premier_5.html","attributes":{"data-id":"id_2001924"},"menu":{"hasChildren":false},"tocID":"id_2001924-d46e215523","topics":[]},{"title":"Choose the FRU to replace","shortdesc":"<p class=\"shortdesc\">Choose which replacement procedure to continue with (Scan Control and Intercom Module (SCIM), keyboard, or mouse).<\/p>","href":"t_ChooseTheFRUToReplace.html","attributes":{"data-id":"id_2014134"},"menu":{"hasChildren":true},"tocID":"id_2014134-d46e215627","next":"id_2014134-d46e215627"},{"title":"Removing LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the GOC and operator workspace before restoring power to these items.<\/p>","href":"t_Removing-LOTO-GOCandOW-Premier_5.html","attributes":{"data-id":"id_2001925"},"menu":{"hasChildren":false},"tocID":"id_2001925-d46e216043","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_62.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e216147","topics":[]},{"title":"Doing a keyboard audio test","shortdesc":"<p class=\"shortdesc\">This diagnostic tests the audio output capability by testing the SCIM communication path. It sends a high-pitched audio command to the keyboard processor.<\/p>","href":"c_Keyboard-Audio-Test_12457750.html","attributes":{"data-id":"id_15666832"},"menu":{"hasChildren":false},"tocID":"id_15666832-d46e216251","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_90.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e216355","topics":[]}]});